<script setup lang="ts">
import {computed,onMounted,ref,shallowRef,watch} from 'vue';
import {useKnowledgePicker} from '../composables/knowledgePicker';
import {unifiedKnowledge,unifiedLearning} from '../services';
import {StudyFilters} from '../../shared/study-query';
import type {Output} from '../../shared/protocol/registry';
import type {PlannerState} from './planner-state';
import UiIcon from './v37/PrototypeIcon.vue';
const props=defineProps<{deckId:string;initial?:PlannerState}>(),emit=defineEmits<{study:[ids:string[],practice?:boolean];back:[];view:[id:string];remember:[state:PlannerState]}>();
const defaults=():PlannerState=>({filters:StudyFilters.parse({}),mode:'all',random:false,count:1,scope:'eligible',weighted:false,seed:''});
const state=ref<PlannerState>(JSON.parse(JSON.stringify(props.initial??defaults())));
const tree=shallowRef<Output<'knowledge.tree.read'>>(),queue=shallowRef<Output<'learning.queue.preview'>>(),error=ref(''),busy=ref(false),moreOptions=ref(false),choosing=ref(false),draftKnowledge=ref<string[]>([]);let request=0;
const picker=useKnowledgePicker(()=>props.deckId);
const items=computed(()=>queue.value?[...queue.value.due,...queue.value.relearn,...queue.value.specialty].filter(c=>state.value.mode==='all'||c.publishedType===state.value.mode):[]);
const regular=computed(()=>items.value.filter(c=>c.reasonCodes.includes('due')||queue.value?.due.some(d=>d.cardId===c.cardId)||queue.value?.relearn.some(d=>d.cardId===c.cardId)));
const specialty=computed(()=>items.value.filter(c=>!regular.value.some(d=>d.cardId===c.cardId)));
function pathLabel(id:string){const out:string[]=[];let n=tree.value?.nodes.find(n=>n.nodeId===id);const seen=new Set<string>();while(n&&!seen.has(n.nodeId)){seen.add(n.nodeId);out.unshift(n.name);n=tree.value?.nodes.find(p=>p.nodeId===n!.parentId);}return out.join(' › ')||'已失效知识点';}
watch(state,()=>{request++;queue.value=undefined;emit('remember',JSON.parse(JSON.stringify(state.value)));},{deep:true,flush:'sync'});
async function preview(){const token=++request;busy.value=true;error.value='';queue.value=undefined;try{const result=await unifiedLearning.queue({deckId:props.deckId,filters:state.value.filters,seed:state.value.seed,limit:100,...(state.value.random?{randomKnowledge:{scope:state.value.scope,count:state.value.count,weighted:state.value.weighted}}:{})});if(token===request)queue.value=result;}catch(e){if(token===request)error.value=String(e);}finally{busy.value=false;}}
async function loadTree(){error.value='';try{tree.value=await unifiedKnowledge.tree({deckId:props.deckId});}catch(e){error.value=String(e);}}
function reset(){state.value=defaults();}
async function choose(){const deckId=props.deckId;try{const result=await picker.open({deckId,initialSelectedIds:choosing.value?draftKnowledge.value:state.value.filters.knowledge,purpose:'filter',allowSelectDescendants:true});if(result.status==='confirmed'&&props.deckId===deckId){draftKnowledge.value=[...result.nodeIds];choosing.value=true;}}catch(e){error.value=String(e);}}
function apply(){state.value.filters.knowledge=[...draftKnowledge.value];choosing.value=false;}
watch(()=>props.deckId,()=>{choosing.value=false;draftKnowledge.value=[];});
onMounted(loadTree);
const reasons:Record<string,string>={session_reserved:'已在其他复盘页面',needs_content_confirmation:'旧题内容需先确认',paused:'已暂停',specialty_excluded:'不满足额外专项条件'};
</script>
<template><section class="r3-filter" aria-label="筛选学习">
 <div class="page-heading"><div><h1>筛选学习</h1><p>根据知识点、时间、学习状态组合条件，生成本次学习集合。</p></div><div class="heading-actions"><button class="button" @click="emit('back')"><UiIcon name="list"/>查看卡片</button><button class="button primary" :disabled="busy||!regular.length" @click="emit('study',regular.map(c=>c.cardId))"><UiIcon name="play"/>开始学习</button></div></div>
 <section class="surface filter-panel"><div class="section-heading"><h2>学习范围</h2><div class="compact-actions"><button class="button small" @click="choose"><UiIcon name="brain"/>选择知识点</button><button class="button small" @click="state.random=!state.random"><UiIcon name="spark"/>随机知识点</button><button class="button small" @click="moreOptions=!moreOptions">更多筛选条件</button><button class="button small" :disabled="busy" @click="preview">{{busy?'正在读取…':'预览学习队列'}}</button></div></div>
 <form @submit.prevent="preview"><fieldset :disabled="busy" style="border:0;padding:0;margin:0"><div class="filter-grid">
 <label class="field-group"><span class="field-label">学习状态</span><select class="select" aria-label="卡片状态" v-model="state.filters.state"><option value="all">全部卡片</option><option value="due">待复盘</option><option value="new">未学习</option><option value="learned">已学习</option><option value="unlinked">未关联知识点</option></select></label>
 <label class="field-group"><span class="field-label">卡片类型（本次预览内）</span><select class="select" aria-label="筛选卡片类型" v-model="state.mode"><option value="all">全部类型</option><option value="question">错题复盘</option><option value="qa">问答记忆</option><option value="direct">直接记忆</option></select></label>
 <label class="field-group"><span class="field-label">时间依据</span><select class="select" aria-label="日期依据" v-model="state.filters.dateField"><option value="lastReviewAt">最近复盘时间</option><option value="firstReviewAt">首次学习时间</option><option value="createdAt">创建时间</option></select></label>
 <label class="field-group"><span class="field-label">时间区间</span><select class="select" aria-label="时间区间" v-model="state.filters.date.range"><option value="all">全部时间</option><option value="7">最近7天</option><option value="30">最近30天</option><option value="custom">自定义区间</option></select></label></div>
 <div v-if="state.filters.date.range==='custom'" class="compact-actions margin-top"><input type="date" aria-label="开始日期" v-model="state.filters.date.start"/><span>至</span><input type="date" aria-label="结束日期" v-model="state.filters.date.end"/></div>
 <div v-if="moreOptions" class="margin-top"><div class="filter-grid margin-top"><label class="field-group"><span class="field-label">标题与正文关键词</span><input aria-label="筛选关键词" v-model="state.filters.query"/></label><label class="field-group"><span class="field-label">学习表现</span><select class="select" v-model="state.filters.performance"><option value="all">全部表现</option><option value="last-failed">最近错误</option><option value="ever-failed">曾经错误</option><option value="uncertain">不确定</option></select></label><label class="field-group"><span class="field-label">排序</span><select class="select" v-model="state.filters.sort"><option value="default">默认队列</option><option value="lastReviewDesc">最近复盘</option><option value="errorCountDesc">错误次数</option><option value="reviewCountAsc">复盘次数少优先</option></select></label><label class="field-group"><span class="field-label">知识点匹配</span><select class="select" v-model="state.filters.match"><option value="any">任意一个</option><option value="all">全部知识点</option></select></label></div><label><input type="checkbox" v-model="state.filters.includeChildren"/>包含下级知识点</label></div>
 <div v-if="state.random" class="filter-grid margin-top"><label class="field-group"><span class="field-label">随机范围</span><select class="select" v-model="state.scope"><option value="eligible">筛选内可用知识点</option><option value="checked">已勾选知识点</option></select></label><label class="field-group"><span class="field-label">抽取数量</span><input aria-label="随机数量" type="number" min="1" max="20" v-model.number="state.count"/></label><label class="field-group"><span class="field-label">随机种子</span><input aria-label="随机种子" v-model="state.seed"/></label><label><input type="checkbox" v-model="state.weighted"/>薄弱优先</label></div>
 <div class="filter-chips"><button v-for="id in state.filters.knowledge" :key="id" type="button" class="pill" @click="state.filters.knowledge=state.filters.knowledge.filter(k=>k!==id)">{{pathLabel(id)}} ×</button><span v-if="!state.filters.knowledge.length" class="tiny-meta">尚未选择知识点，可直接使用其他条件</span><button type="button" class="text-button align-right" @click="reset">重置条件</button></div></fieldset></form>
 <section v-if="choosing" class="margin-top" aria-label="待应用知识点"><strong>待应用知识点（{{draftKnowledge.length}}）</strong><div class="filter-chips"><span v-for="id in draftKnowledge" :key="id" class="pill">{{pathLabel(id)}}</span><span v-if="!draftKnowledge.length">清空知识点范围</span></div><div class="heading-actions margin-top"><button class="button primary" @click="apply">应用知识点</button><button class="button" @click="choosing=false">取消知识点选择</button></div></section></section>
 <p v-if="error" role="alert">{{error}} <button class="button" @click="loadTree">重新读取知识点</button></p>
 <div class="two-column"><section class="surface padded" aria-label="学习队列预览"><div class="section-heading"><h2>符合条件的卡片</h2><span class="tiny-meta">{{queue?items.length+' 张 · 本次队列':'尚未预览'}}</span></div><p class="tiny-meta">按预算返回最多100张；类型仅筛选本次返回队列，不代表全部匹配数量。</p><button v-for="c in items.slice(0,6)" :key="c.cardId" class="mini-row filter-preview-row" @click="emit('view',c.cardId)"><span class="deck-icon"><UiIcon :name="c.publishedType==='question'?'cards':c.publishedType==='qa'?'book':'brain'"/></span><span class="mini-row-main"><strong>{{c.title||'未命名卡片'}}</strong><small>{{{question:'错题复盘',qa:'问答记忆',direct:'直接记忆'}[c.publishedType]}}</small></span><UiIcon name="chevron"/></button><details v-if="items.length>6"><summary>其余 {{items.length-6}} 张队列卡片</summary><button v-for="c in items.slice(6)" :key="c.cardId" class="text-button" @click="emit('view',c.cardId)">{{c.title}}</button></details><div v-if="queue&&!items.length" class="empty-state">此范围暂无可用任务，可调整筛选。</div><div class="heading-actions margin-top"><button class="button primary" :disabled="busy||!regular.length" @click="emit('study',regular.map(c=>c.cardId))">开始本次复盘</button><button v-if="specialty.length" class="button" :disabled="busy" @click="emit('study',specialty.map(c=>c.cardId),true)">开始专项（{{specialty.length}}张）</button></div><p v-for="(n,key) in queue?.excluded" :key="key" class="tiny-meta">{{reasons[key]??key}}：{{n}}</p></section>
 <aside class="surface side-box"><h3>知识点范围</h3><p class="small-muted">可多选知识点，也可随机抽取；不使用演示掌握度。</p><div v-for="id in queue?.selectedKnowledge??state.filters.knowledge" :key="id" class="mini-row"><div class="mini-row-main"><strong>{{pathLabel(id)}}</strong></div></div><button class="button small margin-top" @click="choose"><UiIcon name="brain"/>选择知识点</button></aside></div>
</section></template>
